/**
 * Bundles drizzle-kit's SQL migrations into a TypeScript module that Metro and Jest can import
 * without a Babel plugin for `.sql` files.
 *
 * Usage: node scripts/bundle-migrations.js [--check]
 *   --check  exit with code 1 if the generated module is out of date (does not write).
 */
const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..');
const MIGRATIONS_DIR = path.join(ROOT, 'drizzle');
const OUT_FILE = path.join(ROOT, 'src/db/migrations.generated.ts');

function render() {
  const journal = JSON.parse(
    fs.readFileSync(path.join(MIGRATIONS_DIR, 'meta/_journal.json'), 'utf8'),
  );
  const migrations = {};
  for (const entry of journal.entries) {
    const key = `m${String(entry.idx).padStart(4, '0')}`;
    migrations[key] = fs.readFileSync(path.join(MIGRATIONS_DIR, `${entry.tag}.sql`), 'utf8');
  }
  return [
    '// Generated by scripts/bundle-migrations.js from ./drizzle. Do not edit.',
    '// Regenerate with `npm run db:generate`.',
    '',
    `const journal = ${JSON.stringify(journal, null, 2)};`,
    '',
    `const migrations: Record<string, string> = ${JSON.stringify(migrations, null, 2)};`,
    '',
    'export default { journal, migrations };',
    '',
  ].join('\n');
}

const content = render();
if (process.argv.includes('--check')) {
  const current = fs.existsSync(OUT_FILE) ? fs.readFileSync(OUT_FILE, 'utf8') : '';
  if (current !== content) {
    console.error('src/db/migrations.generated.ts is out of date. Run `npm run db:generate`.');
    process.exit(1);
  }
} else {
  fs.writeFileSync(OUT_FILE, content);
  console.log(`Wrote ${path.relative(ROOT, OUT_FILE)}`);
}
